import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

function Home() {
  const navigate = useNavigate();

  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);

  const [name, setName] = useState("");
  const [price, setPrice] = useState("");

  // Load products
  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    const res = await fetch("http://localhost:5000/api/products");
    const data = await res.json();
    setProducts(data);
  };

  // Add product
  const addProduct = async () => {
    if (!name || !price) {
      alert("Enter product details");
      return;
    }

    await fetch("http://localhost:5000/api/products", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ name, price }),
    });

    setName("");
    setPrice("");
    fetchProducts();
  };

  // Add to cart
  const addToCart = (product) => {
    setCart([...cart, product]);
  };

  return (
    <div style={{ fontFamily: "Arial" }}>
      
      {/* Navbar */}
      <div style={{
        background: "#222",
        color: "white",
        padding: "15px",
        display: "flex",
        justifyContent: "space-between"
      }}>
        <h2>🛒 MyShop</h2>

        <button
          style={{
            padding: "8px 15px",
            background: "red",
            color: "white",
            border: "none",
            cursor: "pointer"
          }}
          onClick={() => {
            localStorage.removeItem("user");
            navigate("/");
          }}
        >
          Logout
        </button>
      </div>

      <div style={{ padding: "20px" }}>

        {/* Add Product */}
        <h2>Add Product</h2>

        <input
          style={{ padding: "8px", marginRight: "10px" }}
          placeholder="Product Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />

        <input
          style={{ padding: "8px", marginRight: "10px" }}
          placeholder="Price"
          value={price}
          onChange={(e) => setPrice(e.target.value)}
        />

        <button
          style={{
            padding: "8px 15px",
            background: "green",
            color: "white",
            border: "none"
          }}
          onClick={addProduct}
        >
          Add Product
        </button>

        {/* Products */}
        <h2 style={{ marginTop: "30px" }}>Products</h2>

        <div style={{
          display: "flex",
          flexWrap: "wrap",
          gap: "20px"
        }}>
          {products.map((p, index) => (
            <div
              key={index}
              style={{
                border: "1px solid #ddd",
                borderRadius: "10px",
                padding: "15px",
                width: "200px",
                boxShadow: "0 2px 5px rgba(0,0,0,0.1)"
              }}
            >
              <h3>{p.name}</h3>
              <p>₹{p.price}</p>

              <button
                style={{
                  width: "100%",
                  padding: "8px",
                  background: "#007bff",
                  color: "white",
                  border: "none",
                  cursor: "pointer"
                }}
                onClick={() => addToCart(p)}
              >
                Add to Cart
              </button>
            </div>
          ))}
        </div>

        {/* Cart */}
        <h2 style={{ marginTop: "30px" }}>Cart</h2>

        <div style={{
          border: "1px solid #ddd",
          padding: "15px",
          borderRadius: "10px"
        }}>
          {cart.length === 0 ? (
            <p>Cart is empty</p>
          ) : (
            cart.map((item, index) => (
              <div
                key={index}
                style={{
                  borderBottom: "1px solid #ddd",
                  marginBottom: "10px",
                  paddingBottom: "10px"
                }}
              >
                <h4>{item.name}</h4>
                <p>₹{item.price}</p>
              </div>
            ))
          )}
        </div>

      </div>
    </div>
  );
}

export default Home;
